const pack = $("Paczka gate").first().json;
const checks = [
  $("Kontrola lint_ltr").first().json,
  $("Kontrola taxonomy_guard").first().json,
  $("Kontrola pytest").first().json,
];
const sev = { OK: 0, Warning: 1, Blocker: 2 };
const all = [pack.status, ...checks.map(c => c.status)];
const status = all.reduce((h, s) => (sev[s] > sev[h] ? s : h), "OK");
const claims = pack.sources.claims_by_status;
const claimRows = Object.keys(claims).map(k => "| " + k + " | " + claims[k] + " |").join("\n") || "| brak | 0 |";
const missing = pack.artifacts.missing;
const qs = pack.markers.open_questions;
const qc = pack.markers.closed_questions;
const src = pack.artifacts.sources;
const artRows = pack.artifacts.required.map(a => "| " + a + " | " + (missing.includes(a) ? "BRAK" : "obecny") + " | " + src[a] + " |").join("\n");
const CHK = {
  1: ["Hipoteza i cel mierzalny", "Zakres i wykluczenia", "Plan badania", "Wariant badania (teoretyczna/eksperymentalna/computational)", "Zalozenia i uproszczenia jawnie opisane", "Definicje i oznaczenia kluczowe"],
  2: ["Klasyfikacja danych", "Retencja i dostep", "Ryzyka z ownerem", "Parametry i warunki brzegowe opisane", "Plan walidacji wewnetrznej (analityczne lub benchmarki)"],
  3: ["Reproducibility", "Niepewnosc i wrazliwosc", "Oddzielone wnioski od faktow", "Zbieznosc i stabilnosc numeryczna (jesli dotyczy)", "Replikacja wynikow (min. 2 warianty)"],
  4: ["Akceptacje kompletne", "Wymagania raportowe", "Pelny zestaw artefaktow teoretycznych"],
}[pack.gate] || [];
const chkTxt = CHK.map(c => "- [ ] " + c + " - do oceny przez czlowieka").join("\n");
const actions = [];
missing.forEach(m => actions.push("| Blocker | Brak artefaktu " + m + " | [DO_UZUPELNIENIA] | [DO_UZUPELNIENIA] |"));
checks.filter(c => c.status !== "OK").forEach(c => actions.push("| " + c.status + " | Kontrola " + c.check + " | [DO_UZUPELNIENIA] | [DO_UZUPELNIENIA] |"));
if (pack.sources.pending_preprints > 0) actions.push("| Warning | Preprinty do weryfikacji: " + pack.sources.pending_preprints + " | [DO_UZUPELNIENIA] | [DO_UZUPELNIENIA] |");
if (pack.markers.placeholders_total > 0) actions.push("| Warning | Znaczniki DO_UZUPELNIENIA: " + pack.markers.placeholders_total + " | [DO_UZUPELNIENIA] | [DO_UZUPELNIENIA] |");
if (qs.length > 0) actions.push("| Warning | Otwarte pytania Q-XXX (" + qs.length + "): " + qs.join(", ") + " | [DO_UZUPELNIENIA] | [DO_UZUPELNIENIA] |");
const actTxt = actions.length ? "| Status | Pozycja | Owner | ETA |\n|---|---|---|---|\n" + actions.join("\n") : "Brak pozycji Warning/Blocker.";
const ph = pack.markers.placeholders_top.map(p => "| " + p.file + " | " + p.count + " |").join("\n") || "| brak | 0 |";
const confidence = status === "OK" ? 0.8 : status === "Warning" ? 0.6 : 0.4;
const ts = new Date().toISOString();
const rows = checks.map(c => "| " + c.check + " | " + c.status + " | " + c.exit_code + " |").join("\n");
const details = checks.filter(c => c.status !== "OK").map(c => "### " + c.check + "\n\n```\n" + String(c.stdout || "").trim().slice(0, 1200) + (c.stderr ? "\n[stderr] " + String(c.stderr).trim().slice(0, 400) : "") + "\n```").join("\n\n");
const report = [
  "# Paczka przed Gate " + pack.gate + " - " + pack.topic,
  "",
  "- Data (UTC): " + ts,
  "- Status roboczy: **" + status + "**",
  "- Pewnosc: " + confidence + " (skala 0-1; ocena automatyczna, tylko kontrole formalne)",
  "- Uwaga: raport nie jest decyzja gate i nie rekomenduje zatwierdzenia. Decyzje Gate 1/2/4 podejmuje czlowiek.",
  "",
  "## 1. Kontrole techniczne",
  "",
  "| Kontrola | Status | Kod wyjscia |",
  "|---|---|---|",
  rows,
  "",
  details,
  "",
  "## 2. Kompletnosc artefaktow (Gate " + pack.gate + ")",
  "",
  "| Artefakt | Stan | Zrodlo wymagania |",
  "|---|---|---|",
  artRows,
  "",
  "Sprawdzana jest tylko obecnosc plikow, nie ich tresc.",
  "",
  "### Kryteria scenariusza (Checklista-Research-Gate) - ocena przez czlowieka",
  "",
  chkTxt,
  "",
  "## 3. Zrodla literatury",
  "",
  "| Status pozycji w logu | Liczba |",
  "|---|---|",
  claimRows,
  "",
  "- Preprinty oczekujace na weryfikacje (do_weryfikacji): " + pack.sources.pending_preprints,
  "",
  "- Process Suite (" + pack.process_suite.file + "): " + (pack.process_suite.present ? "obecny, data pliku " + pack.process_suite.modified : "brak") + ". Status i wnioski ocenia czlowiek; raport ich nie interpretuje.",
  "",
  "## 4. Otwarte luki",
  "",
  "- Znaczniki DO_UZUPELNIENIA: " + pack.markers.placeholders_total,
  "",
  "| Plik | Liczba |",
  "|---|---|",
  ph,
  "",
  "- Otwarte Q-XXX (" + qs.length + "): " + (qs.join(", ") || "brak"),
  "- Zamkniete Q-XXX (" + qc.length + "): " + (qc.join(", ") || "brak"),
  "- Pytanie jest uznane za zamkniete, gdy linia z jego ID zawiera slowo zamkniete/zamknieto (heurystyka; [DO_UZUPELNIENIA] potwierdzenie).",
  "",
  "## 5. Dzialania korygujace (owner i ETA)",
  "",
  actTxt,
  "",
  "## 6. Podsumowanie",
  "",
  pack.gate === 3 ? "Gate 3: agent-conditional pass jest mozliwy tylko przy niskim ryzyku i statusie OK bez uwag krytycznych; ten raport go nie przyznaje." : "",
  status === "OK" ? "Brak krytycznych ryzykow formalnych." : status === "Warning" ? "Ryzyka niekrytyczne: przejrzyj sekcje 3 i 4 przed decyzja." : "Blocker: braki krytyczne (fail_closed) - eskalacja do Orkiestratora i czlowieka.",
  "",
  "## Pytania uzupelniajace",
  "",
  "- Brak pytan automatycznych; pytania Q-XXX z badania sa w sekcji 4.",
  "",
].join("\n");
const slug = pack.topic.replace(/[^A-Za-z0-9._-]/g, "_");
const fname = "gate" + pack.gate + "-" + slug + "-" + ts.replace(/[:.]/g, "-") + ".md";
return [{ json: { status, report, fname, confidence, topic: pack.topic, gate: pack.gate } }];

const d = $input.first().json;
const bin = await this.helpers.prepareBinaryData(Buffer.from(d.report, 'utf8'), d.fname, 'text/markdown');
return [{ json: { fname: d.fname, status: d.status }, binary: { data: bin } }];

const inputData = $input.first().json;
const body = inputData.body || inputData;
const source = inputData.headers ? "api" : "form";
const topic = String(body.topic ?? body["Temat badania"] ?? "").trim();
const rawGate = body.gate ?? body["Gate"];
const gate = Number(rawGate);
let error = "";
if (!topic) error = "Brak parametru 'topic' (Temat badania).";
else if (rawGate === undefined || rawGate === null || rawGate === "") error = "Brak parametru 'gate' (1-4).";
else if (!Number.isInteger(gate) || gate < 1 || gate > 4) error = "Parametr 'gate' musi byc liczba calkowita 1-4.";
return [{ json: { valid: !error, error: error ? "bad_request" : "", detail: error, topic, gate, source } }];

